const [pairLine, listLine] = input.trim().split("\n");
const [a, b] = pairLine.trim().split(/\s+/).map(Number);
const values = listLine.trim().split(/\s+/).map(Number);

const bin8 = (n) => n.toString(2).padStart(8, "0");
const parity = (n) => ((n & 1) === 1 ? "odd" : "even");

console.log(`a     = ${bin8(a)} (${a})`);
console.log(`b     = ${bin8(b)} (${b})`);
console.log(`a & b = ${bin8(a & b)} (${a & b})`);
console.log(`a | b = ${bin8(a | b)} (${a | b})`);
console.log(`a ^ b = ${bin8(a ^ b)} (${a ^ b})`);
console.log(`~a = ${~a}`);
console.log(`${a} is ${parity(a)}, ${b} is ${parity(b)}`);

const unpaired = values.reduce((acc, v) => acc ^ v, 0);
console.log(`unpaired: ${unpaired}`);

