const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");
const count = Number(lines[0]);

const READ = 4;
const WRITE = 2;
const EXEC = 1;
const flagByName = { READ, WRITE, EXEC };

function toRwx(flags) {
  const r = (flags & READ) !== 0 ? "r" : "-";
  const w = (flags & WRITE) !== 0 ? "w" : "-";
  const x = (flags & EXEC) !== 0 ? "x" : "-";
  return `${r}${w}${x}`;
}

let perms = 0;
for (const line of lines.slice(1, count + 1)) {
  const [action, name] = line.trim().split(/\s+/);
  const flag = flagByName[name];
  if (action === "grant") {
    perms |= flag;
  } else if (action === "revoke") {
    perms &= ~flag;
  } else if (action === "toggle") {
    perms ^= flag;
  } else if (action === "check") {
    console.log(`${name}: ${(perms & flag) !== 0 ? "yes" : "no"}`);
  }
}

const bits = perms.toString(2).padStart(3, "0");
console.log(`final: ${bits} ${toRwx(perms)}`);
